import json, gzip, copy
from pathlib import Path
P=Path(__file__).resolve().parent
S=P.parent/'library-site/dist'
def get(i): return json.load(gzip.open(S/'book-records'/(i[1:3]+'.json.gz')))[i]
def source(title,url,**kw): return dict(title=title,url=url,**kw)
date='2026-10-17'
ifo='https://actuaries.org.uk/media/aognluto/allcat1900_202502_isbd_listbyau1.pdf#page=108'
ccfr=source('Valenciennes municipal library · J 4-36 · CCFr', 'https://ccfr.bnf.fr/portailccfr/ark:/16871/00111278843',institution='Bibliothèque municipale de Valenciennes',callNumber='J 4-36',copies=1,type='institutional holding')
bnf=source('BnF · Réserve des livres rares · RÉS V-908', 'https://expositions.bnf.fr/cnac/grand/cir_3607.htm',institution='Bibliothèque nationale de France',callNumber='RÉS V-908',copies=1,type='institutional copy exhibition')
ghent=source('Ghent University source copy · Google Books digitization', 'https://books.google.com/books?id=Cqk_AAAAcAAJ',institution='Ghent University',copies=1,type='institutional source-copy digitization')
if08=source('Institute and Faculty of Actuaries · RKN 20214 · 2025 inventory',ifo,institution='Institute and Faculty of Actuaries',callNumber='RKN 20214',copies=1,type='institutional holding')
if13=source('Institute and Faculty of Actuaries · RKN 20215 · 2025 inventory',ifo,institution='Institute and Faculty of Actuaries',callNumber='RKN 20215',copies=1,type='institutional holding')
worth=source('Edward Worth Library · its 1713 Montmort copy', 'https://mathematics.edwardworthlibrary.ie/probability/montmort/',institution='Edward Worth Library',copies=1,type='institutional copy exhibition')
rsl=source('Russian State Library · H 137/200', 'https://search.rsl.ru/ru/record/01004788583',institution='Russian State Library',callNumber='H 137/200',copies=1,type='institutional holding')
dealer=source('Sophia Rare Books · 1708 first-issue description', 'https://www.sophiararebooks.com/pages/books/4632/pierre-remond-de-montmort/essay-danalyse-sur-les-jeux-de-hazard')
def review(i,title,reason,fields,discrepancies,sources,scope,level='high'):
 return dict(id=i,editionReview=dict(decision='verified_edition' if level=='high' else 'probable_edition',confidence=level,cleanTitle=title,reasoning=reason,checkedFields=[dict(field=f,catalogue=c,source=s) for f,c,s in fields],discrepancies=discrepancies,sources=sources,verificationScope=scope,dateChecked=date))
def survival(r,n,sources,note,scope,confidence='high'):
 r['survivalResearch']=dict(editionMatchConfidence=r['editionReview']['confidence'],evidenceConfidence=confidence,documentedLowerBound=n,countUnit='distinct documented institutional copies',worldwideSurvivingRange=dict(min=n,max=None,confidence='low',isEstimate=False),worldwideEstimate=None,note=note,evidence=sources,editionRelationship=scope,checked=date,method='Conservative enumeration of distinct physical institutional source copies; no extrapolation from digitizations, search hits or auction transactions.',globalEstimateConfidence='unresolved')
 r['survivalEvidence']=[dict(title='Copies identified in independent collections',range=f'At least {n} documented copies · upper bound unknown',summary=note,confidence=confidence,editionRelation=scope,sources=sources)]
 return r
out=[]
scope08='Paris, Jacques Quillau, 1708 first edition, across its issues; family issue and completeness unverified.'
r=review('w647821587e75',"Essay d’analyse sur les jeux de hazard",'The anonymous family card matches the CCFr first-edition title, Paris printer, 1708 date and XXIV, 189, [3] pagination. CCFr attributes the work to Pierre Rémond de Montmort. The card cannot distinguish the two issues described by the IFoA inventory.', [('Title','Essay d’analyse sur les jeux de hazard','Same title; attributed to Pierre Rémond de Montmort'),('Imprint','Paris, Jacques Quillau, 1708','Paris, Jacques Quillau, 1708'),('Extent','XXIV, 189, [3] pages','CCFr: XXIV, 189, [3] pages')],['The card does not describe folding tables or textual issue points; first-issue rarity cannot be transferred to this family copy.'],[ccfr,if08],scope08)
survival(r,4,[ccfr,bnf,if08,ghent],'Four distinct institutional copies are documented: Valenciennes, BnF, IFoA and Ghent. This is a located minimum for the 1708 edition across issues. No worldwide census, reliable upper bound or survival rate was found. Auction appearances were excluded because a copy can be sold repeatedly.',scope08)
r['researchPatch']=dict(title=r['editionReview']['cleanTitle'],year=1708,imprint='Paris: Jacques Quillau, 1708',language='French',summary='A study of chance in card games, dice and related games, using combinatorial reasoning to calculate outcomes and advantages. The first edition appeared in 1708; Montmort expanded it in 1713. The family card describes the 1708 edition.',summarySources=[bnf,ccfr])
r['attributionPatch']=dict(id='a2b30cab1fdf0',name='Pierre Rémond de Montmort',reason='The anonymous 1708 title and exact pagination match the CCFr record explicitly attributed to Montmort.')
r['survivalEvidence'].append(dict(title='Issue-specific market evidence',range='First-issue scarcity · family issue unresolved',summary='A specialist dealer distinguishes an early issue without folding tables and reports a small auction history. This is an attributed market observation, not a survivor census. The family card does not establish this issue.',confidence='low',editionRelation='First issue of 1708 only; not assigned to the family copy.',sources=[dealer,if08]))
out.append(r)
scope13='Paris, Jacques Quillau, 1713 second edition; completeness of folding tables remains unverified.'
r=review('w09b0d7410fc7',"Essay d’analyse sur les jeux de hazard · second edition",'The family card specifies the second edition, Paris, Quillau, 1713, and XLII, 414, [2] pages. IFoA RKN 20215 agrees on those identifying fields. The stated number of folding tables differs, so completeness is not verified.', [('Edition','Seconde édition, 1713','Second edition, 1713'),('Imprint','Paris, Jacques Quillau','Paris, Jacques Quillau'),('Extent','XLII, 414, [2]; 3 folding tables','IFoA: XLII, 414, [2]; 6 folding plates; RSL: XLII, 416; 5 table leaves')],['Folding-table totals differ between the family card and sources; inspect the physical volume before treating it as complete.'],[if13,worth,rsl],scope13)
survival(r,3,[if13,worth,rsl],'Three independent institutional copies are located at IFoA, the Edward Worth Library and the Russian State Library. RSL’s microfilm entry is not an additional physical copy; IFoA’s modern facsimile is excluded. No worldwide upper bound or defensible point estimate was found.',scope13)
r['researchPatch']=dict(title=r['editionReview']['cleanTitle'],year=1713,imprint='Paris: Jacques Quillau, 1713',language='French',summary='The expanded second edition develops Montmort’s treatment of games of chance and includes correspondence with the Bernoullis. The Edward Worth Library illustrates its discussions of dice outcomes and the banker’s advantage in card games.',summarySources=[worth,if13])
r['attributionPatch']=dict(id='a2b30cab1fdf0',name='Pierre Rémond de Montmort',reason='Author attribution independently confirmed by institutional records of both editions.')
out.append(r)
si=source('Smithsonian Libraries · Dibner source copy 39088000877480', 'https://library.si.edu/digital-library/book/methodusinvenie00eule',institution='Smithsonian Libraries',callNumber='39088000877480',copies=1,type='institutional source-copy digitization')
cmu=source('Carnegie Mellon · Posner collection file 517.4 E88M 1744', 'https://iiif.library.cmu.edu/file/Posner_Files_517.4_E88M_1744/Posner_Files_517.4_E88M_1744.pdf',institution='Carnegie Mellon University · Posner Collection',callNumber='517.4 E88M 1744',copies=1,type='institutional copy dossier')
for i in ['wba46e50037bf','w844a05b75c66']:
 full=i=='wba46e50037bf'
 r=review(i,'Methodus inveniendi lineas curvas maximi minimive proprietate gaudentes','The family title, author, Lausanne/Geneva imprint, Bousquet and 1744 date agree with Smithsonian metadata and the Posner copy dossier. '+('The family collation also agrees: [2], 322, [2] pages and five folding plates.' if full else 'This second family card has no usable pagination; the edition connection is strong, but completeness remains unresolved.'),[('Imprint','Lausanne and Geneva, M.-M. Bousquet, 1744','Same places, publisher and year'),('Extent','[2], 322, [2]; five folding plates' if full else 'Pagination not recorded legibly','Smithsonian: [2], 322, [2]; five folding plates')],[] if full else ['No complete family collation; do not apply rarity claims limited to complete copies.'],[si,cmu],'1744 edition; the two family catalogue cards are not assumed to be the same physical book.')
 survival(r,2,[si,cmu],'Two independent institutional copies: Smithsonian and Carnegie Mellon’s Posner Collection. The Internet Archive mirror of the Smithsonian scan counts once. Repeated sale descriptions in the Posner dossier are not additional copies. The worldwide total remains unestimated.','1744 Bousquet edition; complete-copy status of the family item is separate.')
 if full:
  r['bibliographyAssessment']=dict(assessment='Rare when complete with all five plates',confidence='low',matchConfidence='high',applicable=True,referenceYear=1744,editionHeading='1744 first edition, with all five folding plates',editionRelationship='Family card lists all five folding plates, but current physical completeness is uninspected.',scope='Historic dealer assessment preserved in the Posner acquisition file.',reason='A dealer description in the Posner dossier calls complete examples rare. The family catalogue lists five plates. This dated commercial judgment has no numerical threshold or worldwide census.',sources=[cmu],checked=date,method='Explicit attributed qualitative assessment; no conversion to a survivor total.',sourceBias='Historic sale description; market selection and dated opinion.')
 out.append(r)
# Contemporary notice strengthens an existing limitation lead without erasing its date conflict.
i='w6aff8edc0f21';old=get(i)
umi=source('Unione Matematica Italiana · 1937 contemporary publication notice, p. 248','https://www.bdim.eu/item?fmt=pdf&id=BUMI_1937_1_16_5_244_0',type='contemporary publication notice',originalPrintRun=500,accessNote='Indexed full-text passage read; direct PDF retrieval returned an error.')
r=dict(id=i,editionReview=copy.deepcopy(old['editionReview']),survivalResearch=copy.deepcopy(old['survivalResearch']),survivalEvidence=copy.deepcopy(old['survivalEvidence']))
r['editionReview']['sources'].append(umi)
r['editionReview']['reasoning']+=' A contemporary 1937 UMI notice independently describes Zanichelli’s numbered edition of 500; the family date conflict remains.'
r['survivalResearch']['evidence'].append(umi)
r['survivalResearch']['note']+=' A contemporary UMI publication notice corroborates the 500-copy printing. This strengthens the original-run evidence, not a present-day survivor estimate.'
r['survivalEvidence'].append(dict(title='Contemporary confirmation of the printing',range='500 numbered copies originally published',summary='A 1937 UMI notice independently reports the numbered Zanichelli edition and its facsimile format. The catalogue’s 1837 date remains in conflict; 500 is still a conditional ceiling, not a likely count of surviving copies.',confidence='medium',editionRelation='Probable 1937 issue; family date conflict retained.',sources=[umi]))
out.append(r)
(P/'root-results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
print({'reviewed':len(out),'newEvidence':4,'deepenedExisting':1})
